import{_ as t,W as d,s as o,u as r,I as s,ah as i,w as n,Z as p,A as l}from"./chunks/framework.ChbOY6p5.js";import"./chunks/theme.B6FFP-dx.js";const v=JSON.parse('{"title":"通过编写“猜数字”游戏来学习 Ada 编程语言 | LCTT x X-CMD","titleTemplate":false,"description":"通过编写“猜数字”游戏来学习 Ada 编程语言 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"通过编写“猜数字”游戏来学习 Ada 编程语言 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通过编写“猜数字”游戏来学习 Ada 编程语言 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20230109.0 ⭐️⭐️ Learn the Ada programming language by writing a simple game","title":"通过编写“猜数字”游戏来学习 Ada 编程语言","tag":"202301"},"relativePath":"202301/20230109.0 ⭐️⭐️ Learn the Ada programming language by writing a simple game.md","filePath":"[post].md"}'),u={name:"202301/20230109.0 ⭐️⭐️ Learn the Ada programming language by writing a simple game.md"};function g(c,a,m,b,h,T){const e=d("Link");return r(),o("div",null,[a[23]||(a[23]=s("h1",{id:"通过编写-猜数字-游戏来学习-ada-编程语言",tabindex:"-1"},[n("通过编写“猜数字”游戏来学习 Ada 编程语言 "),s("a",{class:"header-anchor",href:"#通过编写-猜数字-游戏来学习-ada-编程语言","aria-label":"Permalink to 通过编写“猜数字”游戏来学习 Ada 编程语言"},"​")],-1)),a[24]||(a[24]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202301/13/173929sbddkk6fbd67uu5v.jpg",alt:""})],-1)),a[25]||(a[25]=s("blockquote",null,[s("p",null,'这个 "猜数字 "游戏是学习新编程语言的一个很好的入门程序，因为它以一种相当直接的方式锻炼了几个常见的编程概念。')],-1)),s("p",null,[a[1]||(a[1]=n("当你想 ")),p(e,{href:"https://opensource.com/article/20/10/learn-any-programming-language"},{default:l(()=>a[0]||(a[0]=[n("学习一种新的编程语言")])),_:1}),a[2]||(a[2]=n(" 时，把注意力放在编程语言的共同点上是很好的："))]),a[26]||(a[26]=i('<ul><li>变量</li><li>表达式</li><li>语句</li></ul><p>这些概念是大多数编程语言的基础。一旦你理解了它们，你就可以开始琢磨其他的东西了。因为编程语言通常有相似之处，一旦你知道一种语言，你就可以通过了解其差异来学习另一种语言的基础知识。</p><p>学习新语言的一个好方法是用一个标准程序进行练习。这使你能够专注于语言，而不是程序的逻辑。在这个系列文章中，我使用了一个“猜数字”的程序，在这个程序中，计算机在 1 到 100 之间挑选一个数字，并要求你猜出来。程序循环进行，直到你猜对数字为止。</p><p>这个程序锻炼了编程语言中的几个概念：</p><ul><li>变量</li><li>输入</li><li>输出</li><li>条件判断</li><li>循环</li></ul><p>这是一个学习新的编程语言的很好的实践实验。</p><h3 id="安装-ada" tabindex="-1">安装 Ada <a class="header-anchor" href="#安装-ada" aria-label="Permalink to 安装 Ada">​</a></h3>',7)),s("p",null,[p(e,{href:"https://opensource.com/article/21/10/learn-ada-2021"},{default:l(()=>a[3]||(a[3]=[n("Ada 编程语言")])),_:1}),a[4]||(a[4]=n(" 是一种独特的、高度结构化的语言，有专门一群开发者使用它。Ada 的工具链是 GNU Ada 开发环境，多被称为 GNAT。"))]),a[27]||(a[27]=i('<p>你可以使用你的发行版的包管理器在 Linux 上安装 GNAT。在 Fedora、CentOS 或类似系统上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install gcc-gnat</span></span></code></pre></div><p>在 Debian、Linux Mint 及衍生版上:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo apt install gnat</span></span></code></pre></div>',4)),s("p",null,[a[6]||(a[6]=n("在 macOS 和 Windows 上，你可以从 ")),p(e,{href:"https://www.adacore.com/download/more"},{default:l(()=>a[5]||(a[5]=[n("Adacore 网站")])),_:1}),a[7]||(a[7]=n(" 下载一个安装程序（从下拉菜单中选择你的平台）。"))]),a[28]||(a[28]=i(`<h3 id="在-ada-中猜数字" tabindex="-1">在 Ada 中猜数字 <a class="header-anchor" href="#在-ada-中猜数字" aria-label="Permalink to 在 Ada 中猜数字">​</a></h3><p>创建一个名为 <code>game.adb</code> 的文件。</p><p>这个程序使用的两个内置 Ada 库：<code>Text_IO</code> 和 <code>Numerics.Discrete_Random</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>with Ada.Text_IO;</span></span>
<span class="line"><span>use Ada.Text_IO;</span></span>
<span class="line"><span>with Ada.Numerics.Discrete_Random;</span></span></code></pre></div><h4 id="过程头" tabindex="-1">过程头 <a class="header-anchor" href="#过程头" aria-label="Permalink to 过程头">​</a></h4><p><ruby>过程<rt>procedure</rt></ruby> 的名称必须与文件的名称一致。第一部分是定义变量。</p><p>注意，<code>discrete_random</code> 是专门针对特定范围的。在这里，允许数字范围：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>procedure Game is</span></span>
<span class="line"><span>   type randRange is range 1..100;</span></span>
<span class="line"><span>   package Rand_Int is new ada.numerics.discrete_random(randRange);</span></span>
<span class="line"><span>   use Rand_Int;</span></span>
<span class="line"><span>   gen : Generator;</span></span>
<span class="line"><span>   num : randRange;</span></span>
<span class="line"><span>   incorrect: Boolean := True;</span></span>
<span class="line"><span>   guess: randRange;</span></span></code></pre></div><h4 id="过程逻辑" tabindex="-1">过程逻辑 <a class="header-anchor" href="#过程逻辑" aria-label="Permalink to 过程逻辑">​</a></h4><p>该逻辑从 <code>reset(gen)</code> 开始。这将初始化随机数发生器，确保每次运行程序时，用 <code>random(gen)</code> 初始化的数字将是不同的。</p><p>下一步是运行循环：</p><ul><li>输出猜测的指令</li><li>读取该行</li><li>将其转换为 <code>randRange</code>。</li><li>将其与数字进行核对</li></ul><p>如果数字匹配，<code>incorrect</code> 被设置为 <code>False</code>，导致循环的下一次迭代退出。</p><p>最后，程序在退出前会打印出对猜测正确性的确认：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>begin</span></span>
<span class="line"><span>   reset(gen);</span></span>
<span class="line"><span>   num := random(gen);</span></span>
<span class="line"><span>   while incorrect loop</span></span>
<span class="line"><span>       Put_Line (&quot;Guess a number between 1 and 100&quot;);</span></span>
<span class="line"><span>       declare</span></span>
<span class="line"><span>          guess_str : String := Get_Line (Current_Input);</span></span>
<span class="line"><span>       begin</span></span>
<span class="line"><span>          guess := randRange&#39;Value (guess_str);</span></span>
<span class="line"><span>       end;</span></span>
<span class="line"><span>       if guess &lt; num then</span></span>
<span class="line"><span>           Put_line(&quot;Too low&quot;);</span></span>
<span class="line"><span>       elsif guess &gt; num then</span></span>
<span class="line"><span>           Put_line(&quot;Too high&quot;);</span></span>
<span class="line"><span>       else</span></span>
<span class="line"><span>           incorrect := False;</span></span>
<span class="line"><span>       end if;</span></span>
<span class="line"><span>   end loop;</span></span>
<span class="line"><span>   Put_line(&quot;That&#39;s right&quot;);</span></span>
<span class="line"><span>end Game;</span></span></code></pre></div><h3 id="编译程序" tabindex="-1">编译程序 <a class="header-anchor" href="#编译程序" aria-label="Permalink to 编译程序">​</a></h3><p>编译 Ada 程序的最简单方法是使用 <code>gnatmake</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ gnatmake game.adb</span></span>
<span class="line"><span>aarch64-linux-gnu-gcc-10 -c game.adb</span></span>
<span class="line"><span>aarch64-linux-gnu-gnatbind-10 -x game.ali</span></span>
<span class="line"><span>aarch64-linux-gnu-gnatlink-10 game.ali</span></span></code></pre></div><p>这将生成一个名为 <code>game</code> 的二进制文件。</p><h3 id="运行程序" tabindex="-1">运行程序 <a class="header-anchor" href="#运行程序" aria-label="Permalink to 运行程序">​</a></h3><p>程序的每次运行都会有一些不同。这是一个例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ./game </span></span>
<span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span>50</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span>75</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span>82</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span>90</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span>87</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>Guess a number between 1 and 100</span></span>
<span class="line"><span>88</span></span>
<span class="line"><span>That&#39;s right</span></span></code></pre></div><h3 id="学习-ada" tabindex="-1">学习 Ada <a class="header-anchor" href="#学习-ada" aria-label="Permalink to 学习 Ada">​</a></h3><p>这个“猜数字”游戏是学习新的编程语言的一个很好的入门程序，因为它以一种相当直接的方式锻炼了几个常见的编程概念。通过在不同的编程语言中实现这个简单的游戏，你可以展示这些语言的一些核心概念，并比较它们的细节。</p><p>你有喜欢的编程语言吗？你会如何用它来写“猜数字”的游戏？请关注本系列文章，看看你可能感兴趣的其他编程语言的例子吧!</p><hr>`,26)),s("p",null,[a[9]||(a[9]=n("via: ")),p(e,{href:"https://opensource.com/article/23/1/learn-ada-simple-game"},{default:l(()=>a[8]||(a[8]=[n("https://opensource.com/article/23/1/learn-ada-simple-game")])),_:1})]),s("p",null,[a[14]||(a[14]=n("作者：")),p(e,{href:"https://opensource.com/users/moshez"},{default:l(()=>a[10]||(a[10]=[n("Moshe Zadka")])),_:1}),a[15]||(a[15]=n(" 选题：")),p(e,{href:"https://github.com/lkxed"},{default:l(()=>a[11]||(a[11]=[n("lkxed")])),_:1}),a[16]||(a[16]=n(" 译者：")),p(e,{href:"https://github.com/geekpi"},{default:l(()=>a[12]||(a[12]=[n("geekpi")])),_:1}),a[17]||(a[17]=n(" 校对：")),p(e,{href:"https://github.com/wxy"},{default:l(()=>a[13]||(a[13]=[n("wxy")])),_:1})]),s("p",null,[a[20]||(a[20]=n("本文由 ")),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>a[18]||(a[18]=[n("LCTT")])),_:1}),a[21]||(a[21]=n(" 原创编译，")),p(e,{href:"https://linux.cn/"},{default:l(()=>a[19]||(a[19]=[n("Linux中国")])),_:1}),a[22]||(a[22]=n(" 荣誉推出"))])])}const x=t(u,[["render",g]]);export{v as __pageData,x as default};
